#!/usr/bin/env python3
"""Keyword census over project .lean files (excluding .lake/). Classifies each
hit as 'code' or 'prose' by stripping nested /- ... -/ block comments and
-- line comments. String literals are skipped (neither code nor prose)."""
import re, sys, json, collections, os
ROOT = sys.argv[1]
KW = ["sorry","axiom","admit","native_decide","implemented_by","extern","unsafe","opaque","set_option","macro","elab"]
files = []
for dp, dns, fns in os.walk(ROOT):
    dns[:] = [d for d in dns if d != ".lake" and not d.startswith(".")]
    for fn in fns:
        if fn.endswith(".lean"):
            files.append(os.path.relpath(os.path.join(dp, fn), ROOT))
files.sort()
def regions(src):
    """yield (kind, start, end) char-offset regions, kind in code/prose."""
    i=0; n=len(src); depth=0; out=[]; cur=0; kind="code"
    while i<n:
        if kind=="code":
            if src.startswith("/-",i):
                out.append(("code",cur,i)); cur=i; kind="block"; depth=1; i+=2; continue
            if src.startswith("--",i):
                j=src.find("\n",i); j=n if j<0 else j
                out.append(("code",cur,i)); out.append(("prose",i,j)); cur=j; i=j; continue
            if src[i]=='"':
                j=i+1
                while j<n and src[j]!='"':
                    if src[j]=='\\': j+=1
                    j+=1
                out.append(("code",cur,i)); out.append(("string",i,j+1)); cur=j+1; i=j+1; continue
            i+=1
        else:
            if src.startswith("/-",i): depth+=1; i+=2; continue
            if src.startswith("-/",i):
                depth-=1; i+=2
                if depth==0: out.append(("prose",cur,i)); cur=i; kind="code"
                continue
            i+=1
    out.append((kind if kind=="code" else "prose",cur,n))
    return out
res={k:{"code":0,"prose":0,"string":0} for k in KW}; hits=collections.defaultdict(list)
for f in files:
    src=open(os.path.join(ROOT,f),encoding="utf-8").read()
    lines=src.splitlines()
    for kind,s,e in regions(src):
        seg=src[s:e]
        for k in KW:
            for m in re.finditer(r"(?<![A-Za-z0-9_.'!?])"+re.escape(k)+r"(?![A-Za-z0-9_'!?])",seg):
                line=src.count("\n",0,s+m.start())+1
                res[k][kind]+=1
                hits[k].append((kind,f,line,lines[line-1].strip()[:140]))
print("FILES",len(files))
print(json.dumps(res,indent=1))
for k in KW:
    for h in hits[k]:
        if k=="sorry" or h[0]!="prose": print(k,*h,sep="\t")
